<template><section class="workspace-page pet-page"><PageHeader title="一路学习，一路陪伴。" description="星粮来自已验证的完成记录。慢慢成长，不需要每天打卡。" eyebrow="我的星航伙伴" /><p v-if="store.error||store.storageError" class="m-error" role="alert">{{ store.error||store.storageError }}<button class="workspace-text-action" @click="store.refresh">重新读取</button></p><div class="pet-layout"><DashboardWidget title="当前小伙伴" :source="'宠物、星粮与装饰保存在本机，按当前账号隔离。'"><div class="pet-showcase"><AIPetAvatar :kind="store.local.pet" :stage="store.pet.stage" :happy="happy" /><div><span class="m-badge m-badge--info">{{ store.pet.stage }} · 等级 {{ store.pet.level }}</span><h2>{{ names[store.local.pet] }}</h2><p>谢谢你，愿意留一点时间给学习。</p></div></div><div class="pet-growth"><div><span>成长经验</span><b>{{ store.pet.current }} / {{ store.pet.next }}</b></div><div class="m-progress"><div class="m-progress__fill" :style="{width:`${store.pet.current/store.pet.next*100}%`}" /></div><p>同行阶段：等级 3 解锁披风；领航阶段：等级 6 解锁星冠。</p></div><div class="pet-feed"><span><MobileIcon name="star" :size="18" /><b>{{ store.local.food }}</b> 份星粮</span><button class="m-btn m-btn--primary" :disabled="store.local.food<1||happy" @click="feed">喂一份星粮</button></div><p v-if="message" role="status" class="workspace-caption">{{ message }}</p><p v-if="!store.local.food" class="workspace-caption">完成清单并保存可获 1 星粮（自报完成），完成服务器练习可获 2 星粮；完成至少 80% 且不少于 1 分钟的专注，可获得星粮。达到有效专注条件可获 3 星粮。同一完成记录仅奖励一次。</p></DashboardWidget><div><DashboardWidget title="选择与你同行的小伙伴"><div class="pet-choices"><button v-for="(name,kind) in names" :key="kind" :aria-pressed="store.local.pet===kind" @click="choose(kind)"><AIPetAvatar :kind="kind" :stage="store.pet.stage" :animated="false" /><span>{{ name }}</span><small>{{ kind===store.local.pet?'正在陪伴':'选择小伙伴' }}</small></button></div></DashboardWidget><DashboardWidget class="pet-log-widget" title="成长记录"><div v-if="!store.local.rewards.length" class="pet-empty-log"><MobileIcon name="book" :size="24" /><p>还没有奖励记录。先完成一次学习，再来看看。</p><RouterLink to="/learn">开始学习 →</RouterLink></div><ul v-else class="pet-log"><li v-for="reward in store.local.rewards.slice(0,12)" :key="reward.id"><span><b>{{ reward.reason }}</b><small>{{ dateLabel(reward.at) }} · 服务器保存记录</small></span><strong>+{{ reward.amount }} 星粮</strong></li></ul><p v-if="store.local.feeds.length" class="workspace-caption">已喂养 {{ store.local.feeds.length }} 次，累计经验 {{ store.local.experience }}。</p></DashboardWidget></div></div><p class="workspace-caption">这是本机陪伴互动，不是学习能力评估。服务器暂未提供宠物奖励对账接口，跨设备不会同步，也不宣称具有跨设备防刷保证。</p></section></template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import PageHeader from '@/mobile/components/PageHeader.vue'
import DashboardWidget from '@/mobile/components/DashboardWidget.vue'
import AIPetAvatar from '@/mobile/components/AIPetAvatar.vue'
import MobileIcon from '@/mobile/components/MobileIcon.vue'
import { useLearningWorkspace } from '@/mobile/stores/learning-workspace'
import { dateLabel } from '@/mobile/data/workspace'
import type { PetKind } from '@/mobile/domain/companion'
const store=useLearningWorkspace(),happy=ref(false),message=ref(''),names:Record<PetKind,string>={fox:'星航狐',cat:'月影猫',rabbit:'云朵兔',owl:'夜航鸮'}
let timeout:ReturnType<typeof setTimeout>|undefined
onMounted(()=>store.refresh());onBeforeUnmount(()=>{if(timeout)clearTimeout(timeout)})
function choose(kind:PetKind){store.local.pet=kind;store.persist();message.value=`${names[kind]}开始陪你学习。`}
function feed(){if(!store.feed())return;happy.value=true;message.value='谢谢你的星粮，成长经验 +10。';timeout=setTimeout(()=>{happy.value=false},1200)}
</script>
<style scoped>.pet-layout{display:grid;gap:20px}.pet-showcase{display:flex;align-items:center;gap:20px}.pet-showcase>.ai-pet-avatar{width:170px;max-width:50%;flex:none}.pet-showcase h2{font-size:25px;margin:12px 0}.pet-showcase p{font-size:14px;line-height:1.8;color:var(--m-text-dim)}.pet-growth{margin:20px 0}.pet-growth>div:first-child{display:flex;justify-content:space-between;font-size:14px;margin-bottom:10px}.pet-growth p{font-size:12px;color:var(--m-text-faint);line-height:1.8}.pet-feed{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.pet-feed>span{display:flex;align-items:center;gap:7px;color:var(--m-gold);font-size:14px}.pet-feed b{font-size:24px}.pet-choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.pet-choices button{border:1px solid var(--m-border);border-radius:16px;background:var(--m-bg);padding:8px 10px 14px;color:var(--m-text);font:inherit;cursor:pointer}.pet-choices button[aria-pressed=true]{background:var(--m-primary-soft);border-color:var(--m-primary)}.pet-choices .ai-pet-avatar{max-width:118px;margin:auto}.pet-choices span,.pet-choices small{display:block}.pet-choices span{font-size:14px}.pet-choices small{font-size:12px;color:var(--m-text-faint);margin-top:6px}.pet-log-widget{margin-top:20px}.pet-log{padding:0;margin:0;list-style:none}.pet-log li{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid var(--m-border)}.pet-log b{font-size:14px}.pet-log small{display:block;font-size:12px;color:var(--m-text-faint);margin-top:6px}.pet-log strong{font-size:13px;color:var(--m-gold);white-space:nowrap}.pet-empty-log{text-align:center;font-size:14px;line-height:1.9;color:var(--m-text-faint)}.pet-empty-log a{color:var(--m-primary);display:inline-flex;align-items:center;min-height:44px;text-decoration:none}@media(min-width:1100px){.pet-layout{grid-template-columns:1.1fr 1fr;align-items:start}.pet-showcase>.ai-pet-avatar{width:220px}}</style>
